/*  _____ _______         _                      _
 * |_   _|__   __|       | |                    | |
 *   | |    | |_ __   ___| |___      _____  _ __| | __  ___ ____
 *   | |    | | '_ \ / _ \ __\ \ /\ / / _ \| '__| |/ / / __|_  /
 *  _| |_   | | | | |  __/ |_ \ V  V / (_) | |  |   < | (__ / /
 * |_____|  |_|_| |_|\___|\__| \_/\_/ \___/|_|  |_|\_(_)___/___|
 *                                _
 *              ___ ___ ___ _____|_|_ _ _____
 *             | . |  _| -_|     | | | |     |  LICENCE
 *             |  _|_| |___|_|_|_|_|___|_|_|_|
 *             |_|
 *
 *   PROGRAMOVÁNÍ  <>  DESIGN  <>  PRÁCE/PODNIKÁNÍ  <>  HW A SW
 *
 * Tento zdrojový kód je součástí výukových seriálů na
 * IT sociální síti WWW.ITNETWORK.CZ
 *
 * Kód spadá pod licenci prémiového obsahu a vznikl díky podpoře
 * našich členů. Je určen pouze pro osobní užití a nesmí být šířen.
 * Více informací na http://www.itnetwork.cz/licence
 */

import React, { useEffect, useState } from "react";
import { useNavigate, useParams } from "react-router-dom";

import { apiGet, apiPost, apiPut } from "../utils/api";

import InputField from "../components/InputField";
import InputSelect from "../components/InputSelect";
import FlashMessage from "../components/FlashMessage";

const InvoiceForm = () => {
    const navigate = useNavigate();
    const { id } = useParams();

    const [sellerListState, setSellerList] = useState([]);
    const [buyerListState, setBuyerList] = useState([]);
    const [sellerState, setSeller] = useState("");
    const [buyerState, setBuyer] = useState("");

    const [invoice, setInvoice] = useState({
        invoiceNumber: "",
        sellerID: sellerState,
        buyerID: buyerState,
        issued: new Date().toISOString().split("T")[0],
        dueDate: new Date(Date.now() + 14 * 24 * 60 * 60 * 1000).toISOString().split("T")[0],
        product: "",
        price: "",
        vat: "21",
        note: "",
    });

    const [sentState, setSent] = useState(false);
    const [successState, setSuccess] = useState(false);
    const [errorState, setError] = useState(null);

    useEffect(() => {
        if (id) {
            apiGet("/api/invoices/" + id).then((data) => {
                console.log("Fetched Invoice:", data); // Debugging log
                setInvoice(data);
                setSeller(data.sellerID);
                setBuyer(data.buyerID);

                // Fetch seller details if sellerID exists
                if (data.sellerID) {
                    apiGet("/api/persons/" + data.sellerID).then((sellerData) => {
                        console.log("Fetched Seller:", sellerData);
                        setSeller(sellerData.id); // Může být sellerData.name podle struktury API
                    }).catch(error => console.error("Error fetching seller:", error));
                }
            });
        }
    }, [id]);


    useEffect(() => {
        apiGet("/api/persons").then((data) => {
            setSellerList(data);
            setBuyerList(data);
        });
    }, []);

    const handleChange = (e) => {
        const { name, value } = e.target;
        if (name === "seller") {
            setSeller(value);
            setInvoice({ ...invoice, sellerID: value });
        } else if (name === "buyer") {
            setBuyer(value);
            setInvoice({ ...invoice, buyerID: value });
        } else {
            setInvoice({ ...invoice, [name]: value });
        }
    };

    const handleSubmit = (e) => {
        e.preventDefault();

        (id ? apiPut("/api/invoices/" + id, invoice) : apiPost("/api/invoices", invoice))
            .then(() => {
                setSent(true);
                setSuccess(true);
                navigate("/invoices");
            })
            .catch((error) => {
                console.log(error.message);
                setError(error.message);
                setSent(true);
                setSuccess(false);
            });
    };

    return (
        <div>
            <h1>{id ? "Upravit" : "Vytvořit"} fakturu</h1>
            <hr />
            {errorState && <div className="alert alert-danger">{errorState}</div>}
            {sentState && (
                <FlashMessage
                    theme={successState ? "success" : ""}
                    text={successState ? "Uložení faktury proběhlo úspěšně." : ""}
                />
            )}
            <form onSubmit={handleSubmit}>
                <InputField
                    required
                    type="text"
                    name="invoiceNumber"
                    min="3"
                    label="Číslo faktury"
                    prompt="Zadejte číslo faktury"
                    value={invoice.invoiceNumber}
                    handleChange={handleChange}
                />

                <InputSelect
                    name="seller"
                    items={sellerListState}
                    label="Prodávající"
                    prompt="Vyberte prodávajícího"
                    value={sellerState}
                    handleChange={handleChange}
                />

                <InputSelect
                    name="buyer"
                    items={buyerListState}
                    label="Kupující"
                    prompt="Vyberte kupujícího"
                    value={buyerState}
                    handleChange={handleChange}
                />

                <InputField
                    required
                    type="date"
                    name="issued"
                    label="Datum vydání faktury"
                    value={invoice.issued}
                    handleChange={handleChange}
                />

                <InputField
                    required
                    type="date"
                    name="dueDate"
                    label="Datum splatnosti faktury"
                    value={invoice.dueDate}
                    handleChange={handleChange}
                />

                <InputField
                    required
                    type="text"
                    name="product"
                    min="3"
                    label="Název produktu"
                    prompt="Zadejte název produktu"
                    value={invoice.product}
                    handleChange={handleChange}
                />

                <InputField
                    required
                    type="text"
                    name="note"
                    min="3"
                    label="Popis"
                    value={invoice.note}
                    handleChange={handleChange}
                />

                <InputField
                    required
                    type="text"
                    name="vat"
                    min="3"
                    label="Daň"
                    value={invoice.vat}
                    handleChange={handleChange}
                />

                <InputField
                    required
                    type="text"
                    name="price"
                    min="3"
                    label="Cena"
                    value={invoice.price}
                    handleChange={handleChange}
                />

                <input type="submit" className="btn btn-primary" value="Uložit" />
            </form>
        </div>
    );
};

export default InvoiceForm;
